export const sessions: Session[] = S.map((s, i) => ({
  ...base(`ses-${i + 1}`, `${bib('10.2, 10.3')}; ${AUTHORED}`, 'WORKING'),
  index: i + 1, title: s.title, arc: `Arc ${s.arc}`, levelRange: s.levels, status: 'PLANNED', visibility: 'DM_ONLY',
  questionMd: `${s.question}\n\n**Anchor from the bible:** ${s.anchor}\n\n**Continuity safeguard:** ${s.safeguard}`,
  prepMd: `> WORKING prep card. Titles, scenes, encounters and clue placement are suggestions to edit; only the cited anchor is canon. Arc name and level range are from the worldbuilding conversation, not the bible.\n\n${s.prep}`,
  dmNotesMd: '', playerRecapMd: '', currentSceneId: i === 0 ? 'scn-1-1' : undefined,
}));

export const scenes: Scene[] = S.flatMap((s, i) => s.scenes.map(([title, descriptionMd, readAloudMd], j): Scene => ({
  ...base(`scn-${i + 1}-${j + 1}`, AUTHORED, 'WORKING'), sessionId: `ses-${i + 1}`, title, descriptionMd, readAloudMd: readAloudMd ?? '', sequence: j + 1,
  status: i === 0 && j === 0 ? 'ACTIVE' : 'PENDING', visibility: 'DM_ONLY',
})));

// ---------------- Mysteries ----------------
const rev = (id: string, title: string, playerTitle: string, sessionIndex: number, src: string, status: 'LOCKED' | 'WORKING' | 'OPEN', f: { truth: string; belief: string; who: string; earliest: string; summary: string; backup: string; terms: string[] }): Revelation => ({
  ...base(id, src, status), title, playerTitle, sessionIndex, privateTruthMd: f.truth, prevailingBeliefMd: f.belief, whoKnowsMd: f.who, earliestRevealMd: f.earliest,
  playerSafeSummaryMd: f.summary, backupMd: f.backup, spoilerTerms: f.terms, status: 'NOT_SEEN', visibility: 'DM_ONLY',
});
export const revelations: Revelation[] = [
  rev('rev-station', 'The blackout began at Exchange 17', 'Where the blackout began', 1, OWNER, 'LOCKED', { truth: 'A degraded regulator at Frostward Thermal Exchange 17, an aging thermal distribution and maintenance facility serving Frostward neighbourhoods, tripped an emergency lockout during the opening blackout. Seven maintenance workers disappeared (see the three revelations below). This is not the retired Station F-17 from the legacy kit.', belief: 'Officially: a brief, contained interruption in which nobody was hurt.', who: 'Facility staff, the constabulary, Thermal Stewardship, Imperial security.', earliest: 'Session 1, by any of three routes.', summary: 'The blackout traces back to Frostward Thermal Exchange 17.', backup: 'The lead is never lost; failure costs time, heat or attention.', terms: [] }),
  rev('rev-trapped', 'Four workers are trapped in the collapsed lower service gallery', 'The trapped workers', 1, OWNER, 'LOCKED', { truth: 'Four of the seven missing maintenance workers are trapped in a collapsed lower service gallery of Exchange 17 and can potentially be rescued. Their names and condition are OPEN. The party is not required to rescue them.', belief: 'Officials say the night shift went home.', who: 'The four trapped workers; anyone who heard the collapse.', earliest: 'Session 1 (roster, tapping), rescue in session 2.', summary: 'Four maintenance workers are trapped in a collapsed lower gallery of Exchange 17.', backup: 'A neighbour or Tarin hears the tapping even if the party never searches.', terms: [] }),
  rev('rev-detained', 'Two workers are held by Imperial security', 'The detained workers', 2, OWNER, 'LOCKED', { truth: 'Two of the seven were detained by Imperial security after encountering suppressed maintenance reports. Their names and where exactly they are held are OPEN. What becomes of them depends on the party and later events.', belief: 'The ledger says "pending review"; nobody official will say more.', who: 'Imperial security; a booking-desk clerk; neighbours who saw the vans.', earliest: 'Session 1 (witnesses, ledger); acted on in session 3.', summary: 'Two of the missing workers were taken by Imperial security.', backup: 'The ledger entry and the witnesses are independent; either is enough.', terms: [] }),
  rev('rev-ilan', 'Ilan Rook vanished deeper inside Exchange 17', 'Ilan Rook', 2, OWNER, 'LOCKED', { truth: 'Ilan Rook, the seventh worker, disappeared deeper inside the exchange. His final fate is NOT predetermined: it depends on the party\'s actions and later events. His personality, motives and species are OPEN.', belief: 'Officially he never signed in.', who: 'Nobody for certain; his coworkers know where he usually worked.', earliest: 'Session 2 (locker, trail, badge log).', summary: 'One worker, Ilan Rook, vanished deeper inside Exchange 17.', backup: 'Any of the three leads is enough; none is required.', terms: [] }),
  rev('rev-wear', 'The Everflame is failing for real engineering reasons', 'Why the heat is failing', 2, bib('4.1'), 'LOCKED', { truth: 'Centuries-old stabilization systems, deferred replacement, degraded components and hard energy balancing. Not sabotage, not a curse. Imperial engineers understand much of it but cannot build a replacement sun.', belief: 'Broadcasts blame unlicensed Resonants; the street suspects sabotage.', who: 'Senior Stewardship engineers and the Empress.', earliest: 'Sessions 1-5, increasingly.', summary: 'The heat failures come from old, worn machinery and years of deferred repair, not from an attack.', backup: 'Any honest engineer can explain it once protected.', terms: [] }),
  rev('rev-allocation', 'Who is cut off is a policy choice', 'Who decides who freezes', 5, bib('4.2'), 'LOCKED', { truth: 'The technical necessity can be genuine while the choice of which communities are sacrificed is policy. Crown and Sanctum keep redundant service.', belief: 'Officially: unavoidable arithmetic.', who: 'Stewardship planners, prefects, the Chancery.', earliest: 'Session 2 onward; unmistakable by session 6.', summary: 'The shortage is real, but the inner rings keep spare capacity while outer districts are cut.', backup: 'The Mercy Decree itself makes it plain.', terms: ['Mercy Decree'] }),
  rev('rev-cinders', 'An organized underground exists: the Cinder Network', 'Who is leaving the crates', 3, bib('9.1'), 'LOCKED', { truth: 'One organized, locally founded underground. Mutual aid, diversion, intelligence, clandestine communications, occasional sabotage. Not automatically heroic; not a mandatory patron.', belief: 'Rumours of "ash-marks"; the ORS suspects cells.', who: 'Its members; partially the ORS.', earliest: 'Hints in sessions 1-3; contact optional from session 4.', summary: 'There is an organized underground in the outer rings. People call them the Cinders.', backup: 'A party that refuses them still reaches every central revelation.', terms: ['Cinder', 'Cinders', 'Cinder Network'] }),
  rev('rev-nyc', 'Solmourn is old New York City', "The city's buried name", 8, bib('3.1'), 'LOCKED', { truth: 'Solmourn is built on and through the ruins of New York City; the Everflame hangs above former Midtown Manhattan; the outer city reaches Mahwah/Ramapo.', belief: 'Nobody thinks about what was here before.', who: 'No one alive.', earliest: 'Sessions 8-9 by default; earlier only through extraordinary play.', summary: 'Solmourn is built on the ruins of a far older city called New York.', backup: 'A second copy of the overlay in a sealed municipal stair.', terms: ['New York', 'NYC', 'Manhattan', 'Midtown', 'Mahwah', 'Ramapo', 'New Jersey'] }),
  rev('rev-embers', 'Nine original Embers', 'Nine lights on an old map', 8, bib('1.2, 2.1'), 'LOCKED', { truth: 'Nine artificial suns appeared at once at nine places. The ~10 AS survey names all nine. It is history: it does not show whether any other still functions, and it explains nothing about how they were made.', belief: 'Solmourn believes it is alone.', who: 'No one in Solmourn - not the Empress, the ORS, the Cinders or the Vigil.', earliest: 'Sessions 8-9.', summary: 'A seven-century-old survey shows nine cities like Solmourn across the world. Whether any still exists is unknown.', backup: 'A survey benchmark and a damaged duplicate in the map room.', terms: ['Ember', 'Embers', 'Vesperdeep', 'Kharos', 'Aureth', 'Namaris', 'Sevrin', 'Orrakai', 'Caldris', 'Azmara', 'nine cities', 'other cities', 'Reykjavík', 'Cairo', 'Paris', 'Mumbai', 'Seoul', 'Tokyo', 'São Paulo', 'Lagos'] }),
  rev('rev-nine-rays', "The Vigil's nine rays once meant the nine Embers", 'What the nine rays meant', 9, bib('7.2'), 'LOCKED', { truth: 'The Vigil arose before the ~50 AS isolation; its nine rays referenced the nine Embers. The meaning was forgotten and reinterpreted as virtues.', belief: 'Nine virtues or sacred qualities.', who: 'No one.', earliest: 'After the map; perceptive players may connect it themselves.', summary: 'The nine rays of the Vigil\'s disk once stood for nine cities, not nine virtues.', backup: 'An old liturgy whose "virtues" read like place names.', terms: [] }),
  rev('rev-relay', 'The Old Relay was an inter-Ember communications link', 'What the old machine was for', 9, bib('9.2'), 'LOCKED', { truth: 'Part of the pre-isolation inter-Ember network; decommissioned ~50 AS, salvaged ~430 AS. Long-range capability dormant. Not a Concordance device, not a map, not an explanation of the sun.', belief: 'The Cinders think it is an old emergency transmitter.', who: 'No one understands its purpose.', earliest: 'Exposure sessions 4-5; meaning after the map; optional attempt sessions 10-12.', summary: 'The underground\'s old transmitter was built to talk to other cities.', backup: 'Non-Cinder parties can find a second, dead unit in the archive.', terms: ['Old Relay', 'Relay Nine'] }),
  rev('rev-collective', 'A lost collective phenomenon lit the first suns (Concordance)', 'Something people can only do together', 11, bib('1.2, 1.3'), 'LOCKED', { truth: 'Concordance: rare, emergent group harmony among Resonance participants, producing effects beyond their separate powers. Its first emergence was spontaneous and crisis-born, and created the nine suns. Completely lost as a usable art. False Dawns were sometimes failed spontaneous events.', belief: 'No concept exists. Records say "unexplained".', who: 'No one. A few Aureth researchers suspect an unnamed collective phenomenon and cannot prove it.', earliest: 'Sessions 10-12, if earned through observation, experiment and risk.', summary: 'Under the right conditions, people working Resonance together can do what none could do alone. Nobody has known how for centuries.', backup: 'Understanding can stay partial; the finale offers engineering and political paths too.', terms: ['Concordance', 'False Dawn', 'False Dawns'] }),
  rev('rev-sun', 'The natural sun still exists behind Dissonance', 'What became of the sun', 12, bib('1.1'), 'LOCKED', { truth: 'The sun was not destroyed. Dissonance, a planet-scale interference phenomenon created by Resonance experimentation, prevents its light and heat reaching the surface. It is not a creature and has no intentions.', belief: 'The sun is gone.', who: 'No one.', earliest: 'Late investigation or endgame.', summary: 'The sun is still there. Something is stopping its light and warmth from reaching the world.', backup: 'Old observatory instruments and a physical model of the interference.', terms: ['Dissonance', 'natural sun'] }),
  rev('rev-unbound', 'The Unbound prophecy', 'An old prophecy', 13, bib('1.4'), 'OPEN', { truth: 'A suppressed, obscure prophecy concerns a learned Resonant and/or group able to unify the six disciplines. Individual or collective: OPEN. Wording, origin and reliability: OPEN. Never designate a PC.', belief: 'Almost unknown; where known, dismissed or feared.', who: 'Fragments in Vigil and ORS files.', earliest: 'Whenever the party goes looking; never as an announcement.', summary: '', backup: 'Its meaning is determined by play.', terms: ['Unbound', 'Sixth Canticle', 'Canticle'] }),
];

const clue = (id: string, title: string, playerTitle: string, sessionIndex: number, revelationIds: string[], privateTextMd: string, playerTextMd: string, discoveryRoutes: string[], extra: Partial<Clue> = {}): Clue => ({
  ...base(id, AUTHORED, 'WORKING'), title, playerTitle, sessionIndex, revelationIds, privateTextMd, playerTextMd, discoveryRoutes,
  status: 'NOT_SEEN', required: false, evidenceItem: '', discoveredBy: [], visibility: 'DM_ONLY', ...extra,
});
